(function(){const n=new URLSearchParams(location.search).get("id"),e=window.OasisAuth.findReserva(n),t=document.getElementById("rBody");if(!e){document.getElementById("rTitle").textContent="Reserva no encontrada",t.innerHTML='<p class="lede">Este enlace no corresponde a una reserva guardada en este navegador.</p>';return}document.getElementById("rTitle").textContent=e.vehiculo,t.innerHTML=`<div class="reserva-card">
    <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:1rem">
      <p class="eyebrow">${e.id}</p><span class="reserva-estado">${e.status}</span>
    </div>
    <div class="reserva-grid">
      <div><span style="font-size:.7rem;color:var(--muted)">CLIENTE</span><b style="font-family:var(--font-body);font-size:1rem">${e.nombre}</b></div>
      <div><span style="font-size:.7rem;color:var(--muted)">RECOGIDA</span><b>${e.fechaRecogida||"\u2014"}</b></div>
      <div><span style="font-size:.7rem;color:var(--muted)">REGRESO</span><b>${e.fechaRegreso||"\u2014"}</b></div>
      <div><span style="font-size:.7rem;color:var(--muted)">LUGAR</span><b style="font-family:var(--font-body);font-size:.95rem">${e.pickup||"\u2014"}</b></div>
    </div>
  </div>`})();
